int vfs_rename(struct inode *old_dir, struct dentry *old_dentry,
               struct inode *new_dir, struct dentry *new_dentry,
               struct inode **delegated_inode, unsigned int flags)
{
    int error;

    if (dentry_same_name(old_dentry, new_dentry))
        return 0;

    error = inode_permission(old_dir, MAY_WRITE | MAY_EXEC);
    if (error)
        return error;

    error = inode_permission(new_dir, MAY_WRITE | MAY_EXEC);
    if (error)
        return error;

    if (S_ISDIR(old_dentry->d_inode->i_mode)) {
        error = inode_permission(old_dentry->d_inode, MAY_EXEC);
        if (error)
            return error;
    }

    error = check_name_collision(old_dir, old_dentry, new_dir, new_dentry);
    if (error)
        return error;

    if (flags & RENAME_EXCHANGE) {
        error = do_rename_exchange(old_dir, old_dentry, new_dir, new_dentry);
    } else {
        error = do_rename(old_dir, old_dentry, new_dir, new_dentry);
    }

    if (!error) {
        fsnotify_move(old_dir, new_dir, old_dentry, new_dentry);
        d_move(old_dentry, new_dentry);
    }

    return error;
}

int vfs_rename(struct inode *old_dir, struct dentry *old_dentry,
               struct inode *new_dir, struct dentry *new_dentry,
               struct inode **delegated_inode, unsigned int flags)
{
    int error;
    struct inode *old_inode = old_dentry->d_inode;
    struct inode *new_inode = new_dentry->d_inode;
    struct super_block *old_sb = old_dir->i_sb;
    struct super_block *new_sb = new_dir->i_sb;

    if (old_sb != new_sb)
        return -EXDEV;

    error = security_inode_rename(old_dir, old_dentry, new_dir, new_dentry);
    if (error)
        return error;

    if (flags & RENAME_EXCHANGE) {
        error = inode_permission(new_dir, MAY_WRITE | MAY_DELETE_CHILD);
        if (error)
            return error;
    }

    if (S_ISDIR(old_inode->i_mode)) {
        error = inode_permission(old_inode, MAY_EXEC);
        if (error)
            return error;
    }

    error = inode_permission(new_dir, MAY_WRITE | MAY_CREATE_DIR);
    if (error)
        return error;

    if (new_inode) {
        error = inode_permission(new_inode, MAY_WRITE | MAY_DELETE);
        if (error)
            return error;
    }

    if (flags & RENAME_EXCHANGE) {
        error = do_exchange_renames(old_dir, old_dentry,
                                    new_dir, new_dentry);
    } else {
        error = do_rename(old_dir, old_dentry, new_dir, new_dentry);
    }

    if (!error) {
        d_move(old_dentry, new_dentry);
        fsnotify_rename(old_dir, old_dentry, new_dir, new_dentry);
    }

    return error;
}

int vrename(struct inode *old_dir, struct dentry *old_dentry, struct inode *new_dir, struct dentry *new_dentry, struct inode **delegated_inode, unsigned int flags) {
    int error;

    if (dentry_same_name(old_dentry, new_dentry))
        return 0;

    error = inode_permission(old_dir, MAY_WRITE | MAY_EXEC);
    if (error)
        return error;

    error = inode_permission(new_dir, MAY_WRITE | MAY_EXEC);
    if (error)
        return error;

    if (S_ISDIR(old_dentry->d_inode->i_mode)) {
        error = inode_permission(old_dentry->d_inode, MAY_EXEC);
        if (error)
            return error;
    }

    if (new_dentry->d_inode) {
        error = inode_permission(new_dir, MAY_DELETE | MAY_WRITE);
        if (error)
            return error;

        if (S_ISDIR(new_dentry->d_inode->i_mode)) {
            error = -EEXIST;
            if (flags & RENAME_EXCHANGE)
                error = 0;
            if (error)
                return error;
        }
    }

    if (flags & RENAME_EXCHANGE) {
        if (!new_dentry->d_inode)
            return -ENOTEMPTY;

        if (S_ISDIR(old_dentry->d_inode->i_mode) != S_ISDIR(new_dentry->d_inode->i_mode))
            return -EXDEV;
    }

    if (old_dentry->d_inode->i_nlink >= (unsigned)MAX_LINK_COUNT)
        return -EMLINK;

    error = -ENOMEM;
    *delegated_inode = NULL;

    mutex_lock(&old_dir->i_mutex);
    mutex_lock(&new_dir->i_mutex);

    if (old_dentry->d_inode) {
        error = old_dir->i_op->rename(old_dir, old_dentry, new_dir, new_dentry);
        if (!error) {
            if (flags & RENAME_EXCHANGE) {
                error = new_dir->i_op->rename(new_dir, new_dentry, old_dir, old_dentry);
                if (error) {
                    new_dir->i_op->rename(old_dir, old_dentry, new_dir, new_dentry);
                    error = -EIO;
                }
            }
        }
    } else {
        error = new_dir->i_op->create(new_dir, new_dentry, old_dentry->d_inode->i_mode & S_IALLUGO);
        if (!error) {
            error = old_dir->i_op->rmdir(old_dir, old_dentry);
            if (error) {
                new_dir->i_op->rmdir(new_dir, new_dentry);
                error = -EIO;
            }
        }
    }

    mutex_unlock(&new_dir->i_mutex);
    mutex_unlock(&old_dir->i_mutex);

    if (!error) {
        fsnotify_move(old_dir, new_dir, old_dentry, new_dentry);
        dput(old_dentry);
        dput(new_dentry);
    }

    return error;
}

int vfs_rename(struct inode *old_dir, struct dentry *old_dentry,
               struct inode *new_dir, struct dentry *new_dentry,
               struct inode **delegated_inode, unsigned int flags)
{
    int error;

    if (old_dentry == new_dentry)
        return 0;

    error = security_path_rename(&old_dentry->d_parent->d_path,
                                 old_dentry, &new_dentry->d_parent->d_path,
                                 new_dentry, flags);
    if (error)
        return error;

    if (!old_dir->i_op->rename)
        return -EPERM;

    d_drop(new_dentry);
    dget(old_dentry);

    error = old_dir->i_op->rename(old_dir, old_dentry, new_dir, new_dentry, flags);
    if (!error) {
        fsnotify_move(old_dir, old_dentry, new_dir, new_dentry);
        dput(old_dentry);
    }
    return error;
}

int vfat_rename(struct inode *old_dir, struct dentry *old_dentry,
                struct inode *new_dir, struct dentry *new_dentry,
                struct inode **delegated_inode, unsigned int flags)
{
    struct inode *old_inode = old_dentry->d_inode;
    struct inode *new_inode = new_dentry->d_inode;
    int error;

    if (old_inode == new_inode && old_dir == new_dir)
        return 0;

    error = inode_permission(old_dir, MAY_WRITE | MAY_EXEC);
    if (error)
        return error;

    error = inode_permission(new_dir, MAY_WRITE | MAY_EXEC);
    if (error)
        return error;

    if (S_ISDIR(old_inode->i_mode)) {
        error = inode_permission(old_inode, MAY_EXEC);
        if (error)
            return error;
    }

    if (new_inode) {
        error = inode_permission(new_inode, MAY_WRITE | MAY_EXEC);
        if (error)
            return error;
    }

    if (S_ISDIR(old_inode->i_mode)) {
        if (flags & RENAME_EXCHANGE) {
            if (!new_inode || !S_ISDIR(new_inode->i_mode))
                return -EINVAL;
        } else {
            if (new_inode && !S_ISDIR(new_inode->i_mode))
                return -ENOTDIR;
        }
    }

    error = -ENAMETOOLONG;
    if (old_dentry->d_name.len > VFAT_MAX_NAME_LEN ||
        new_dentry->d_name.len > VFAT_MAX_NAME_LEN)
        goto out;

    error = old_dir->i_op->rename(old_dir, old_dentry, new_dir, new_dentry, flags);
    if (error)
        goto out;

    if (flags & RENAME_EXCHANGE) {
        if (new_inode) {
            new_inode->i_ctime = current_time(new_inode);
            mark_inode_dirty(new_inode);
        }
    }

    old_inode->i_ctime = current_time(old_inode);
    mark_inode_dirty(old_inode);

    if (new_inode) {
        new_inode->i_ctime = current_time(new_inode);
        mark_inode_dirty(new_inode);
    }

    if (flags & RENAME_EXCHANGE) {
        new_dir->i_ctime = new_dir->i_mtime = current_time(new_dir);
        mark_inode_dirty(new_dir);
        old_dir->i_ctime = old_dir->i_mtime = current_time(old_dir);
        mark_inode_dirty(old_dir);
    }

out:
    return error;
}
